#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    /* 第一行按整数输出 */
    printf("%d\n", n);

    /* 关键：n / 2 是整数除法，7 / 2 得到 3，小数部分被直接丢掉。
       写成 n / 2.0 之后，n 会先被隐式转换成 double，结果才是 3.5。 */
    printf("%.1f\n", n / 2.0);
    return 0;
}

