#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    /* sizeof 是运算符，不是函数：sizeof(int) 直接给出这个类型占多少字节。
       注意别把 4、8 写死——内存布局由平台决定，用 sizeof 算出来的才是对的。 */
    printf("char: %zu\n", n * sizeof(char));
    printf("int: %zu\n", n * sizeof(int));

    /* float 和 int 都是 4 字节，但 float 能表示的整数范围小得多，
       因为它把一部分位用来存指数了（详见下面第 3 节）。 */
    printf("float: %zu\n", n * sizeof(float));
    printf("double: %zu\n", n * sizeof(double));
    return 0;
}

#include <stdio.h>

int main() {
    char c;
    /* %c 读入一个字符。注意：%c 不会自动跳过空格和换行，输入里多余的空白要小心 */
    scanf("%c", &c);

    /* char 本质上是 1 字节的小整数。同一个变量换个格式符，看到的就是它的 ASCII 码 */
    printf("%d\n", c);

    /* 'a' - 'A' 就是 32。写成两者相减比写死 32 更能说明意图：
       大写字母排在 65~90，小写字母排在 97~122，中间正好差 32 */
    printf("%c\n", c + ('a' - 'A'));
    return 0;
}

