#include <stdio.h>

int main() {
    double x;
    /* 读 double 用 %lf；printf 输出 double 用 %f，两者不一样，别记混 */
    scanf("%lf", &x);

    /* 强制类型转换：(int)x 把小数部分直接丢掉（向 0 截断），不四舍五入。
       负数也一样：-2.7 变成 -2，而不是向下去取整的 -3 */
    int n = (int)x;
    printf("%d\n", n);

    /* x - n：一边是 double、一边是 int，相减时 int 会被隐式提升成 double，
       结果仍是小数。所以这一行不会因为类型不同而算错 */
    printf("%.2f\n", x - n);
    return 0;
}

#include <stdio.h>

int main() {
    unsigned int n;
    /* %u 是无符号整数的格式符。用 %d 读 3000000000 这种数会读成负数 */
    scanf("%u", &n);

    /* 关键：unsigned int 的运算结果保证「按 2^32 取模」，
       所以 3000000000 * 2 不会变成负数，而是绕回 1705032704。
       反过来，有符号 int 溢出在 C 标准里是未定义行为，结果不可预测，不能依赖 */
    printf("%u\n", n * 2);
    return 0;
}

