#include <stdio.h>

/* #define 是预处理指令：编译前把代码里所有的 PI 原样替换成 3.14159。
   注意行尾不写分号——写了分号，替换出来的就变成 3.14159; ，会直接编译报错 */
#define PI 3.14159

int main() {
    int r;
    scanf("%d", &r);

    /* 2 * PI * r：PI 被替换成小数，所以 r 会被隐式提升成 double，结果是小数。
       要是把它定义成 #define PI 3，全程就变成整数运算，周长会算成整数 */
    printf("%.2f\n", 2 * PI * r);
    printf("%.2f\n", PI * r * r);
    return 0;
}
